hooks.command:
python3 -c "
import json, sys, os, stat, tempfile
try:
    data = json.load(sys.stdin)
except Exception:
    data = {}
sid = ''.join(c for c in str(data.get('session_id', '')) if c.isalnum() or c in '-_')
marker = ''
if sid:
    base = os.path.join(tempfile.gettempdir(), 'cc-baseline-%d' % os.getuid())
    try:
        os.mkdir(base, 0o700)
    except FileExistsError:
        pass
    try:
        st = os.lstat(base)
        if stat.S_ISDIR(st.st_mode) and st.st_uid == os.getuid() and not (st.st_mode & 0o077):
            marker = os.path.join(base, 'e2e-guide-' + sid)
    except OSError:
        marker = ''
boundary = open('{{HOME}}/.claude/memory/reference_subagent_boundary.md').read()
guide = open('{{HOME}}/.claude/memory/reference_e2e_manager_guide.md').read()
if marker:
    try:
        os.close(os.open(marker, os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, 'O_NOFOLLOW', 0), 0o600))
    except FileExistsError:
        sys.exit(0)
    except OSError:
        pass
context = '# reference_subagent_boundary.md\n' + boundary + '\n\n# reference_e2e_manager_guide.md\n' + guide
print(json.dumps({'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'additionalContext': context}}))
"
